const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=value=>/^https?:\/\//.test(value||'')||/^\/(?!\/)/.test(value||'')?esc(value):'#';
const inline=value=>esc(value).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
const date=value=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const reader=document.getElementById('reader');
let articles=[],trigger,fontSize=19,pageTitle=document.title,archiveRevision=null,programs=[],currentEditionId=null;
const imageLabels={'photo':'보도 사진','video-still':'방송 스틸','thumbnail':'원방송 썸네일','generated-illustration':'AI 생성 삽화','diagram':'자료'};
function visualFigure(v,{listing=false,eager=false}={}){return `<figure class="editorial-figure${v.kind==='diagram'?' data-figure':''}${listing?' listing-figure':''}"><img src="${safeUrl(v.url)}" alt="${esc(v.alt)}" width="${Number(v.width)||1000}" height="${Number(v.height)||680}" loading="${eager?'eager':'lazy'}"${eager?' fetchpriority="high"':''}><figcaption><span class="visual-label">${esc(imageLabels[v.kind]||'자료 이미지')}</span> ${esc(v.caption)} · ${esc(v.credit)}${v.licenseUrl?` <a href="${safeUrl(v.licenseUrl)}" target="_blank" rel="noopener noreferrer">이용 조건 ↗</a> · ${esc(v.transformation||'크기 축소·JPEG 변환')}`:''}${v.sourceUrl?` <a href="${safeUrl(v.sourceUrl)}" target="_blank" rel="noopener noreferrer">원출처 ↗</a>`:''}</figcaption></figure>`;}
const figure=(a,options)=>visualFigure(a.visual,options);
const broadcastDate=value=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',weekday:'short'}).format(new Date(value+'T12:00:00+09:00'));
const programName=a=>programs.find(p=>p.id===a.episode?.programId)?.name||a.category;
const episodeDay=a=>`${broadcastDate(a.episode.broadcastDate)} ${a.episode.dateBasis==='published'?'공개':a.episode.dateBasis==='title'?'방송 제목 기준':'방송'}${a.episode.publishedDate&&a.episode.publishedDate!==a.episode.broadcastDate?' · '+broadcastDate(a.episode.publishedDate)+' 공개':''}`;
function episodeLinks(a){if(!a.episode)return '';const e=a.episode,peers=articles.filter(x=>x.episode?.programId===e.programId).sort((x,y)=>y.episode.broadcastDate.localeCompare(x.episode.broadcastDate));return `<nav class="episode-links" aria-label="회차 연결"><a class="watch-broadcast" href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer"><span class="play-mark" aria-hidden="true">▶</span><span>원본 방송 보기 ↗ · 약 ${Math.ceil(e.durationSeconds/60)}분</span></a><a href="/#program-${encodeURIComponent(e.programId)}">${esc(programName(a))} 회차 목록 →</a>${peers.filter(x=>x.id!==a.id).slice(0,3).map(x=>`<a href="${articleLink(x)}">${esc(broadcastDate(x.episode.broadcastDate))} 방송 · ${esc(x.title)}</a>`).join('')}</nav>`;}
const articleLink=(a,editionId=currentEditionId)=>`${editionId?'/?edition='+encodeURIComponent(editionId):''}#article/${encodeURIComponent(a.id)}`;
function prose(a){return a.bodyParagraphs.map((p,i)=>(p.startsWith('## ')?`<h2>${esc(p.slice(3))}</h2>`:`<p>${inline(p)}</p>`)+(a.supportingVisuals||[]).filter(v=>v.afterParagraph===i).map(v=>visualFigure(v)).join('')).join('');}
function watchImages(){document.querySelectorAll('img').forEach(img=>{if(img.dataset.watched)return;img.dataset.watched='true';img.addEventListener('error',()=>{img.classList.add('image-failed');const notice=document.createElement('p');notice.className='image-unavailable';notice.textContent=img.closest('.issue-cover')?'표지 미리보기를 불러오지 못했습니다. 아래 링크에서 PDF를 열 수 있습니다.':img.closest('.official-entry,.review-feature')?'방송 이미지를 불러오지 못했습니다. 원문·방송 링크는 계속 이용할 수 있습니다.':'이미지를 불러오지 못했습니다. 기사 본문은 계속 읽을 수 있습니다.';img.after(notice);},{once:true});});}
function progress(){const range=reader.scrollHeight-reader.clientHeight;document.getElementById('reading-progress-bar').style.width=(range>0?Math.max(0,Math.min(100,reader.scrollTop/range*100)):0)+'%';}
reader.addEventListener('scroll',progress,{passive:true});
function openArticle(id){
 const a=articles.find(x=>x.id===id);trigger=reader.open?trigger:document.activeElement;
 const content=document.getElementById('article-content');
 if(a){const reading=Math.max(1,Math.ceil((a.lead+a.bodyParagraphs.join('')).length/500));document.title=a.title+' | 위클리 스픽스';content.innerHTML=`${archiveRevision?`<p class="archive-notice">이전 발행 기록입니다. <a href="/?edition=${encodeURIComponent(archiveRevision)}#article/${encodeURIComponent(a.id)}">교정된 최신판으로 읽기 →</a></p>`:''}<span class="eyebrow">${esc(programName(a))} · ${esc(a.genre)}</span><h1 id="article-title">${esc(a.title)}</h1><p class="subtitle">${esc(a.subtitle)}</p><p class="byline">${esc(a.author)}<br>${a.episode?`${esc(episodeDay(a))} · 출연 ${esc(a.episode.guests.join('·'))}${a.episode.hosts.length?' · 진행 '+esc(a.episode.hosts.join('·')):''}`:`입력 ${date(a.publishedAt)}`} · 읽는 데 약 ${reading}분</p>${episodeLinks(a)}<div class="article-prose"><p class="article-lead">${inline(a.lead)}</p>${figure(a,{eager:true})}${prose(a)}</div><aside class="source-box"><strong>방송·참고 자료</strong>${a.sources.map(s=>`<a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}<details><summary>자료 확인 범위</summary><p>${esc(a.verificationNote)}</p></details></aside>`;}
 else{document.title='기사를 찾을 수 없습니다 | 위클리 스픽스';content.innerHTML='<div class="error" role="alert"><h1 id="article-title">기사를 찾을 수 없습니다</h1><p>기사 주소를 확인하거나 목록에서 다시 선택해 주세요.</p></div>';}
 if(!reader.open)reader.showModal();reader.scrollTop=0;document.body.style.overflow='hidden';
 const copy=content.querySelector('.article-prose');if(copy)fontSize=parseFloat(window.getComputedStyle(copy).fontSize)||fontSize;
 progress();document.getElementById('copy-status').textContent='';document.getElementById('close-reader').focus();watchImages();
}
function closeArticle(){reader.close();history.replaceState(null,'',location.pathname+location.search);}
document.getElementById('close-reader').onclick=closeArticle;document.getElementById('bottom-close').onclick=closeArticle;
reader.addEventListener('close',()=>{document.body.style.overflow='';document.title=pageTitle;trigger?.focus();});
reader.addEventListener('cancel',()=>history.replaceState(null,'',location.pathname+location.search));
document.getElementById('font-up').onclick=()=>{fontSize=Math.min(25,fontSize+1);reader.style.setProperty('--reading-size',fontSize+'px');progress();};
document.getElementById('font-down').onclick=()=>{fontSize=Math.max(16,fontSize-1);reader.style.setProperty('--reading-size',fontSize+'px');progress();};
document.getElementById('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);document.getElementById('copy-status').textContent='기사 주소를 복사했습니다.';}catch{document.getElementById('copy-status').textContent='주소창의 기사 주소를 복사해 주세요.';}};
function route(){if(location.hash.startsWith('#article/')){try{openArticle(decodeURIComponent(location.hash.slice(9)));}catch{openArticle('');}}else if(reader.open)reader.close();}
window.addEventListener('hashchange',route);
function settleAnchor(){const id=location.hash.slice(1);if((['weekly','principles','articles','content','programs'].includes(id)||id.startsWith('program-'))&&window.requestAnimationFrame)window.requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView());}
const sectionLabel=category=>({'스픽스 레이다':'스픽스 레이다','커버스토리':'커버스토리 · 이슈 기획','이슈 기획':'커버스토리 · 이슈 기획','Who Speaks':'방송을 깊이 읽다','오피니언':'오피니언 · 월드','월드':'오피니언 · 월드','컬처·라이프':'컬처 · 지방시대','지방시대':'컬처 · 지방시대','자료 읽기':'컬처 · 지방시대'}[category]||category);
function contents(items,editionId){const groups=new Map();for(const a of items){const name=sectionLabel(a.category);if(!groups.has(name))groups.set(name,[]);groups.get(name).push(a);}return `<div class="contents-grid">${[...groups].map(([name,list])=>`<section class="contents-section"><h3>${esc(name)}</h3>${list.map(a=>`<article class="contents-item">${a.visual.kind!=='diagram'?`<figure class="contents-photo"><a href="${articleLink(a,editionId)}"><img src="${safeUrl(a.visual.url)}" alt="${esc(a.visual.alt)}" width="${a.visual.width}" height="${a.visual.height}" loading="lazy"></a><figcaption>${a.visual.kind==='generated-illustration'?'AI 생성 삽화 · ':''}${esc(a.visual.credit)}</figcaption></figure>`:''}<h4><a href="${articleLink(a,editionId)}">${esc(a.title)}</a></h4><p>${esc(a.subtitle)}</p></article>`).join('')}</section>`).join('')}</div>`;}
function issueCard(i){const published=i.status==='published';return `<article class="issue-card">${published?`<div class="issue-cover"><img src="/images/editions/${encodeURIComponent(i.id)}-cover.jpg" alt="위클리 스픽스 ${esc(i.period)} 발행호 표지" width="595" height="842" loading="lazy"></div>`:'<div class="issue-fallback">위클리 스픽스</div>'}<div class="issue-info"><span class="status">${published?(i.revisionOf?'개정판':'발행호'):'편집 중'}</span><h3 class="issue-title">${esc(i.title)}</h3><p>대상 기간 ${esc(i.period)}</p>${published?`<p>발행 ${date(i.publishedAt)}${i.articleSnapshots?' · '+i.articleSnapshots.length+'개 기사':''} · ${i.pages||i.pdfReview?.pages||50}페이지</p><div class="issue-actions"><a class="read-link" href="/?edition=${encodeURIComponent(i.id)}">웹으로 읽기 →</a><a class="read-link" href="${safeUrl(i.pdfUrl)}">PDF 보기 ↓</a></div>`:'<p>기사와 지면 검토를 마친 뒤 공개합니다.</p>'}</div></article>`;}
async function loadIssueContents(edition){try{const res=await fetch(`/api/editions/${encodeURIComponent(edition.id)}.json`);if(!res.ok)throw Error('HTTP');const issue=await res.json();if(!Array.isArray(issue.articleSnapshots))return;document.getElementById('issue-contents').innerHTML='<h3 class="issue-index-label">이번 호에 실린 기사</h3>'+contents(issue.articleSnapshots,issue.id);watchImages();settleAnchor();}catch{document.getElementById('issue-contents').innerHTML='<p class="byline">목차를 불러오지 못했습니다. 위의 웹으로 읽기에서 주간호를 열어 주세요.</p>';}}
const episodeActions=a=>`<div class="episode-actions"><a href="${articleLink(a)}">리뷰 읽기 →</a><a class="watch-broadcast" href="${safeUrl(a.episode.url)}" target="_blank" rel="noopener noreferrer"><span class="play-mark" aria-hidden="true">▶</span><span>원본 방송 보기 ↗</span></a></div>`;
function renderPrograms(enabled,period){
 const section=document.getElementById('programs');section.hidden=!enabled;if(!enabled)return;
 const episodes=articles.filter(a=>a.episode&&(!period||a.episode.broadcastDate>=period.start&&a.episode.broadcastDate<=period.end)).sort((a,b)=>b.episode.broadcastDate.localeCompare(a.episode.broadcastDate));
 const regular=programs;
 document.getElementById('review-period').textContent=period?`${period.start.replaceAll('-','. ')} – ${period.end.replaceAll('-','. ')} 방송`:'';
 const dayOf=a=>new Date(a.episode.broadcastDate+'T12:00:00+09:00').getUTCDay();
 const corner=(p,day)=>{const list=episodes.filter(a=>a.episode.programId===p.id&&(p.schedule||day===null||dayOf(a)===day));const latest=list[0];return `<article class="schedule-corner"><h4><a href="#program-${esc(p.id)}">${esc(p.name)}</a></h4>${p.schedule?.time?`<p>${esc(p.schedule.time)} 방송</p>`:''}${latest?`<p class="schedule-date">${esc(episodeDay(latest))}</p><p class="schedule-title">${esc(latest.title)}</p>${episodeActions(latest)}`:'<p>리뷰 준비 중</p><a class="schedule-source" href="'+safeUrl(p.sourceUrl)+'" target="_blank" rel="noopener noreferrer">코너 방송 보기 ↗</a>'}</article>`;};
 document.getElementById('week-overview').innerHTML=[[1,'월'],[2,'화'],[3,'수'],[4,'목'],[5,'금'],[6,'토'],[0,'일']].map(([day,label])=>{const list=regular.filter(p=>p.schedule?p.schedule.days.includes(day):episodes.some(a=>a.episode.programId===p.id&&dayOf(a)===day));return `<section class="weekday-section" data-weekday="${day}" aria-labelledby="weekday-${day}"><h3 id="weekday-${day}">${label}<small>요일</small></h3>${list.map(p=>corner(p,day)).join('')||'<p class="weekday-empty">검토된 회차<br>준비 중</p>'}</section>`;}).join('');
 const specials=programs.filter(p=>p.kind==='special');document.getElementById('special-programs').innerHTML=specials.length?'<section class="special-broadcasts"><h3>특집 · 수시 방송</h3><div>'+specials.map(p=>corner(p,null)).join('')+'</div></section>':'';
 document.getElementById('program-count').textContent=`${new Set(episodes.map(a=>a.episode.programId)).size}개 코너 · ${episodes.length}회 방송`;
 document.getElementById('program-list').innerHTML=programs.map(p=>{const list=episodes.filter(a=>a.episode.programId===p.id);if(!list.length)return '';return `<section id="program-${esc(p.id)}" class="program-group" data-program="${esc(p.id)}"><div class="program-heading"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></div>${list.length?`<div class="episode-grid">${list.map((a,i)=>`<article class="episode-card">${figure(a,{listing:true})}<div class="episode-copy"><p class="episode-date">${esc(episodeDay(a))} · ${esc(a.episode.guests.join('·'))}</p><h4><a href="${articleLink(a)}">${esc(a.title)}</a></h4><p class="episode-intro">${esc(a.lead.slice(0,130))}${a.lead.length>130?'…':''}</p>${episodeActions(a)}</div></article>`).join('')}</div>`:'<p>검토를 마친 회차부터 소개합니다.</p>'}${list.length>1?`<details class="past-episodes"><summary>지난 회차 ${list.length-1}회</summary>${list.slice(1).map(a=>`<p><a href="${articleLink(a)}">${esc(broadcastDate(a.episode.broadcastDate))} · ${esc(a.title)}</a> · <a href="${safeUrl(a.episode.url)}" target="_blank" rel="noopener noreferrer">원본 방송 ↗</a></p>`).join('')}</details>`:''}</section>`;}).join('');
 const supplements=articles.filter(a=>!a.episode);document.getElementById('supplementary-reading').innerHTML=supplements.length?'<div class="section-heading"><h3>스픽스 신문에서 함께 읽기</h3><p>방송과 함께 읽을 칼럼과 기사</p></div><div class="supplement-grid">'+supplements.map(a=>`<article><span class="eyebrow">신문 읽기</span><h4><a href="${articleLink(a)}">${esc(a.title)}</a></h4><p>${esc(a.subtitle)}</p></article>`).join('')+'</div>':'';
 watchImages();
}
document.addEventListener('click',async event=>{
 const button=event.target.closest?.('[data-copy-source]');if(!button)return;
 const status=button.closest('.source-actions')?.querySelector('.source-copy-status');
 try{await navigator.clipboard.writeText(button.dataset.copySource);if(status)status.textContent='원문 주소를 복사했습니다.';}
 catch{if(status)status.textContent='복사할 주소: '+button.dataset.copySource;}
});
function renderOfficialPrograms(directory){
 document.getElementById('programs').hidden=false;document.getElementById('programs-heading').textContent='스픽스 리뷰';
 document.querySelector('#programs .section-heading p').textContent='공식 기사와 원본 방송';
 const entries=[...directory.entries].sort((a,b)=>b.displayDate.localeCompare(a.displayDate)||b.publishedAt.localeCompare(a.publishedAt)),period=directory.reviewPeriod;
 const inWeek=entries.filter(e=>e.displayDate>=period.start&&e.displayDate<=period.end),dayOf=e=>new Date(e.displayDate+'T12:00:00+09:00').getUTCDay();
 const stamp=e=>`${broadcastDate(e.displayDate)} ${e.broadcastDate?'방송':'기사 게시 · 방송일 미확인'}`;
 const links=e=>`<div class="episode-actions source-actions"><a class="official-article-link" href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">스픽스 원문 읽기 ↗</a>${e.videoUrl?`<a class="watch-broadcast" href="${safeUrl(e.videoUrl)}" target="_blank" rel="noopener noreferrer"><span class="play-mark" aria-hidden="true">▶</span><span>원본 방송 보기 ↗</span></a>`:''}<button type="button" class="source-copy" data-copy-source="${esc(e.url)}" aria-label="${esc(e.title)} 원문 주소 복사">주소 복사</button><span class="source-copy-status" role="status"></span></div>`;
 const image=(e,hero=false)=>e.image?`<a class="broadcast-preview" href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer"><img src="${safeUrl(e.image.url)}" alt="${esc(e.image.alt)}" width="${Number(e.image.width)}" height="${Number(e.image.height)}" loading="${hero?'eager':'lazy'}"${hero?' fetchpriority="high"':''}><span>스픽스 공식 방송</span></a>`:'';
 const item=e=>`<article class="official-entry">${image(e)}<div class="official-entry-copy"><p class="schedule-date">${esc(stamp(e))}</p><h4><a class="official-title" href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${esc(e.title)}</a></h4>${links(e)}</div></article>`;
 let feature=document.getElementById('review-feature');if(!feature){feature=document.createElement('div');feature.id='review-feature';document.getElementById('review-period').before(feature);}
 feature.className='review-feature';feature.innerHTML=entries.length?`<div class="feature-main">${image(entries[0],true)}<p class="feature-kicker">최근 방송 · ${esc(programs.find(p=>p.id===entries[0].programId)?.name||'스픽스')}</p><h2><a href="${safeUrl(entries[0].url)}" target="_blank" rel="noopener noreferrer">${esc(entries[0].title)}</a></h2><p class="schedule-date">${esc(stamp(entries[0]))}</p>${links(entries[0])}</div><aside class="feature-aside" aria-label="함께 볼 공식 기사">${entries.slice(1,3).map(e=>`<article>${image(e)}<p class="feature-kicker">${esc(programs.find(p=>p.id===e.programId)?.name||'스픽스')}</p><h3><a href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)}</a></h3><p class="schedule-date">${esc(stamp(e))}</p>${links(e)}</article>`).join('')}</aside>`:'';
 let help=document.getElementById('source-help');if(!help){help=document.createElement('details');help.id='source-help';feature.after(help);}help.className='source-help';help.innerHTML='<summary>원문이 열리지 않을 때</summary><p>스픽스 원문은 새 창으로 열립니다. 접속이 거부되면 주소를 복사해 Chrome·Edge 등 일반 브라우저에서 열어 보세요. 아래 원본 방송에서도 해당 내용을 확인할 수 있습니다.</p>';
 let calendarHeading=document.getElementById('review-calendar-heading');if(!calendarHeading){calendarHeading=document.createElement('h2');calendarHeading.id='review-calendar-heading';calendarHeading.textContent='요일별 방송 코너';document.getElementById('review-period').before(calendarHeading);}
 document.getElementById('review-period').textContent=`${period.start.replaceAll('-','. ')} – ${period.end.replaceAll('-','. ')} · 공식 기사`;
 document.querySelector('.schedule-note').textContent='공식 기사 제목을 그대로 싣고 스픽스 원문으로 연결합니다. 방송일이 확인되지 않은 기사는 게시일 기준으로 표시합니다. 매주 고정 편성표가 아닙니다.';
 document.getElementById('week-overview').innerHTML=[[1,'월'],[2,'화'],[3,'수'],[4,'목'],[5,'금'],[6,'토'],[0,'일']].map(([day,label])=>{const list=inWeek.filter(e=>dayOf(e)===day),ids=[...new Set(list.map(e=>e.programId))];return `<section class="weekday-section" data-weekday="${day}" aria-labelledby="weekday-${day}"><h3 id="weekday-${day}">${label}<small>요일</small></h3>${ids.map(id=>`<div class="schedule-corner"><h4><a href="#program-${esc(id)}">${esc(programs.find(p=>p.id===id)?.name)}</a></h4>${list.filter(e=>e.programId===id).map(e=>`<article class="schedule-source-entry"><p class="schedule-date">${esc(stamp(e))}</p><h4><a href="${safeUrl(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)}</a></h4>${links(e)}</article>`).join('')}</div>`).join('')||'<p class="weekday-empty">연결할 공식 기사<br>확인 중</p>'}</section>`;}).join('');
 document.getElementById('special-programs').innerHTML='';document.querySelector('.review-heading h2').textContent='코너별 공식 기사';
 document.getElementById('program-count').textContent=`${entries.length}개 공식 기사 · 제목을 누르면 스픽스 원문으로 이동합니다`;
 document.getElementById('program-list').innerHTML=programs.map(p=>{const list=entries.filter(e=>e.programId===p.id);return list.length?`<section id="program-${esc(p.id)}" class="program-group official-program" data-program="${esc(p.id)}"><div class="program-heading"><h3>${esc(p.name)}</h3><p>스픽스 공식 기사</p></div><div class="official-list">${list.slice(0,3).map(item).join('')}</div>${list.length>3?`<details class="official-archive"><summary>지난 공식 기사 ${list.length-3}건 더 보기</summary><div class="official-list">${list.slice(3).map(item).join('')}</div></details>`:''}</section>`:'';}).join('');
 document.getElementById('supplementary-reading').innerHTML='';
}
function previousWeekEdition(editions){
 const today=new Date(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'T00:00:00Z');const monday=new Date(today);monday.setUTCDate(today.getUTCDate()-(today.getUTCDay()+6)%7);
 return editions.filter(i=>{const m=/^(\d{4})\.(\d{1,2})\.(\d{1,2})[–—~-](?:(\d{4})\.)?(?:(\d{1,2})\.)?(\d{1,2})$/.exec(i.period||'');if(i.status!=='published'||!m)return false;const end=Date.UTC(Number(m[4]||m[1]),Number(m[5]||m[2])-1,Number(m[6]));return end<monday.getTime();}).sort((a,b)=>b.period.localeCompare(a.period)||(Date.parse(b.publishedAt)||0)-(Date.parse(a.publishedAt)||0))[0];
}
async function load(){try{
 const params=new URLSearchParams(location.search);let editionId=params.get('edition');if(editionId&&!/^[a-zA-Z0-9_-]{1,100}$/.test(editionId))throw Error('Invalid edition');
 const res=await fetch(editionId?`/api/editions/${encodeURIComponent(editionId)}.json`:'/api/home');if(!res.ok)throw Error('HTTP');let raw=await res.json();
 if(!editionId&&params.get('view')==='weekly'){const chosen=previousWeekEdition(raw.editions);if(!chosen){document.body.classList.add('weekly-mode');document.getElementById('weekly-nav').setAttribute('aria-current','page');document.getElementById('lead').innerHTML='<p>지난주 발행호를 준비하고 있습니다.</p>';document.getElementById('updated').textContent='발행 대기';return;}editionId=chosen.id;const issue=await fetch(`/api/editions/${encodeURIComponent(editionId)}.json`);if(!issue.ok)throw Error('Weekly unavailable');raw=await issue.json();}
 if(editionId&&raw.supersededBy&&!new URLSearchParams(location.search).has('archive')){const next=raw.supersededBy;if(!/^[a-zA-Z0-9_-]{1,100}$/.test(next))throw Error('Invalid revision');const newer=await fetch(`/api/editions/${encodeURIComponent(next)}.json`);if(!newer.ok)throw Error('Revision unavailable');raw=await newer.json();editionId=next;history.replaceState(null,'','/?edition='+encodeURIComponent(next)+location.hash);}
 currentEditionId=editionId||null;archiveRevision=editionId?raw.supersededBy||null:null;
 const data=editionId?{articles:raw.articleSnapshots,updatedAt:raw.publishedAt,editions:[raw]}:raw;articles=data.articles;programs=data.programs||[];document.body.classList.toggle('weekly-mode',!!editionId);document.getElementById(editionId?'weekly-nav':'home-nav').setAttribute('aria-current','page');
 if(editionId&&raw.supersededBy){document.getElementById('articles').insertAdjacentHTML('beforebegin',`<p class="archive-notice">이전 발행 기록입니다. <a href="/?edition=${encodeURIComponent(raw.supersededBy)}${esc(location.hash)}">교정된 최신판으로 읽기 →</a></p>`);}
 if(editionId){document.title=raw.title+' | 위클리 스픽스';document.getElementById('page-label').textContent='주간호 · '+raw.period+(raw.revisionOf?' · 개정판':'');document.getElementById('weekly-heading').textContent='이 주간호 읽기';}
 pageTitle=document.title;document.getElementById('updated').textContent=data.updatedAt?`${editionId?'발행':'최근 기사'} ${date(data.updatedAt)}`:'새 기사를 준비하고 있습니다.';
 const official=!editionId&&raw.homepageMode==='official-links';
 const hasPrograms=official||(!editionId&&programs.length&&articles.some(x=>x.episode));
 const a=(editionId?articles.find(x=>x.id===raw.coverArticleId):hasPrograms?articles.find(x=>x.id===raw.featuredEpisodeId)||articles.find(x=>x.episode):articles.find(x=>x.visual.kind==='generated-illustration'))||articles[0];
 if(hasPrograms)document.getElementById('page-label').textContent=official?'스픽스 공식 기사 안내':'방송 한 편을 읽는 시간';
 document.getElementById('lead').innerHTML=a?`<article class="lead-story">${figure(a,{listing:true,eager:true})}<div><span class="eyebrow">${esc(programName(a))} · ${esc(a.genre)}</span><h1><a href="${articleLink(a)}">${esc(a.title)}</a></h1><p class="subtitle">${esc(a.subtitle)}</p><p class="byline">${a.episode?esc(broadcastDate(a.episode.broadcastDate))+' 방송 · '+esc(a.episode.guests.join('·')):date(a.publishedAt)+' · 위클리 스픽스 편집부'}</p>${!editionId?`<p class="story-summary">${esc(a.lead.length>175?a.lead.slice(0,175)+'…':a.lead)}</p>`:''}<a class="read-link" href="${articleLink(a)}">기사 읽기 →</a></div></article>`:'<p class="error">출고 검토를 마친 기사를 준비하고 있습니다.</p>';
 const rest=articles.filter(x=>x.id!==a?.id&&(!hasPrograms||x.episode));document.getElementById('more').innerHTML=rest.length?(editionId?'<h2 class="rail-heading">이 주간호의 다른 기사</h2>'+contents(rest):'<h2 class="rail-heading">함께 읽는 기사</h2>'+rest.map((a,i)=>`<article class="story-card">${i===0&&a.visual.kind!=='diagram'?figure(a,{listing:true}):''}<span class="eyebrow">${esc(a.category)}</span><h2><a href="${articleLink(a)}">${esc(a.title)}</a></h2><p>${esc(a.subtitle)}</p><span class="byline">${a.episode?esc(broadcastDate(a.episode.broadcastDate))+' 방송':date(a.publishedAt)}</span></article>`).join('')):'';
 document.getElementById('more').hidden=!rest.length;
 const editions=[...data.editions].sort((a,b)=>(Date.parse(b.publishedAt)||0)-(Date.parse(a.publishedAt)||0));
 const latest=editions.find(i=>i.status==='published'),featured=latest||editions[0],archive=editions.filter(i=>i.status==='published'&&i.id!==latest?.id&&(i.revisionOf||i.id)!==(latest?.revisionOf||latest?.id));
 const pdfIssue=editionId?raw:latest;
 const pdfHeader=document.getElementById('header-edition');
 pdfHeader.hidden=!(pdfIssue?.status==='published'&&/^\/(?!\/).*\.pdf$/.test(pdfIssue.pdfUrl||''));
 if(!pdfHeader.hidden)pdfHeader.innerHTML=`<div class="header-edition-copy"><span class="eyebrow">${editionId?'이 주간호':'최신 주간호'} · ${esc(pdfIssue.period)}</span><strong>${esc(pdfIssue.title)}</strong><span class="header-edition-pages">${Number(pdfIssue.pages||pdfIssue.pdfReview?.pages)||''}면</span></div><div class="header-edition-actions"><a class="pdf-preview" href="${safeUrl(pdfIssue.pdfUrl)}" target="_blank" rel="noopener">PDF 펼쳐보기 ↗</a><a class="pdf-download" href="${safeUrl(pdfIssue.pdfUrl)}" download="speaks-weekly-${esc(pdfIssue.id)}.pdf"><span aria-hidden="true">↓</span> 주간지 PDF 다운로드</a></div>`;
 document.getElementById('editions').innerHTML=featured?issueCard(featured)+(archive.length?`<details class="issue-archive"><summary>이전 발행호 ${archive.length}개</summary>${archive.map(i=>`<a href="/?edition=${encodeURIComponent(i.id)}&archive=1">${esc(i.period)} · ${esc(i.title)} · 보존본</a>`).join('')}</details>`:''):'<p>첫 주간지를 준비하고 있습니다.</p>';
 if(official)renderOfficialPrograms(raw.officialDirectory);else renderPrograms(hasPrograms,raw.reviewPeriod);document.getElementById('weekly').hidden=!editionId;document.getElementById('articles').hidden=!!hasPrograms;watchImages();route();settleAnchor();
 }catch{document.getElementById('lead').innerHTML='<div class="error" role="alert">기사를 불러오지 못했습니다. <button id="retry">다시 불러오기</button></div>';document.getElementById('updated').textContent='기사 연결 확인 필요';document.getElementById('retry').onclick=load;}}
load();
